def transform(grid):
 g=[r[:] for r in grid]; pts={}
 for i,row in enumerate(g):
  for j,v in enumerate(row):
   if v: pts.setdefault(v,[]).append((i,j))
 for v,ps in pts.items():
  if len(ps)==2:
   (r,c),(R,C)=ps; dr=1 if R>r else -1; dc=1 if C>c else -1
   if abs(R-r)==abs(C-c):
    for k in range(1,abs(R-r)): g[r+k*dr][c+k*dc]=v
 return g

def transform(grid):
 g=[x[:] for x in grid]; d={}
 for r in range(len(g)):
  for c in range(len(g[0])):
   if g[r][c]: d.setdefault(g[r][c],[]).append((r,c))
 for v,p in d.items():
  a,b=p
  if abs(a[0]-b[0])==abs(a[1]-b[1]):
   for r in range(min(a[0],b[0])+1,max(a[0],b[0])):
    c=a[1]+(r-a[0])*(1 if b[1]>a[1] else -1); g[r][c]=v
 return g
